const load=(key,fallback)=>{try{return JSON.parse(localStorage.getItem(key))||fallback}catch{return fallback}};
const fileDB=new Promise((resolve,reject)=>{const req=indexedDB.open('raduga-files',1);req.onupgradeneeded=()=>req.result.createObjectStore('files');req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)});
async function saveFile(id,file){const db=await fileDB;return new Promise((resolve,reject)=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').put(file,String(id));tx.oncomplete=resolve;tx.onerror=()=>reject(tx.error)})}
async function getFile(id){const db=await fileDB;return new Promise((resolve,reject)=>{const req=db.transaction('files').objectStore('files').get(String(id));req.onsuccess=()=>resolve(req.result);req.onerror=()=>reject(req.error)})}
async function deleteFile(id){const db=await fileDB;return new Promise(resolve=>{const tx=db.transaction('files','readwrite');tx.objectStore('files').delete(String(id));tx.oncomplete=resolve})}
let groups=load('raduga-groups',seedGroups),resources=load('raduga-resources',seedResources),favorites=load('raduga-favorites',[]),level='all',resourceKind='all',examSection='all',view='oge';
