groups=groups.map(g=>{const go=/^go\s*getter/i.test(String(g.series||''))||/^Go Getter/.test(g.name);const own=/^Own(?: It!)? [234]$/.test(g.name);return {...g,series:go?'Go\nGetter':own?'Own It!':g.series,name:own?g.name.replace(/^Own(?: It!)? /,'Own It! '):g.name}});localStorage.setItem('raduga-groups',JSON.stringify(groups));
const $=s=>document.querySelector(s),$$=s=>document.querySelectorAll(s);const cloudSnapshot=()=>({groups:[...groups],students,resources,favorites,tasks,dayTasks,lessons,examDate});const persist=(immediate=false)=>{localStorage.setItem('raduga-groups',JSON.stringify(groups));localStorage.setItem('raduga-resources',JSON.stringify(resources));localStorage.setItem('raduga-favorites',JSON.stringify(favorites));localStorage.setItem('raduga-tasks',JSON.stringify(tasks));localStorage.setItem('raduga-exam-date',examDate);localStorage.setItem('raduga-day-tasks',JSON.stringify(dayTasks));localStorage.setItem('raduga-lessons',JSON.stringify(lessons));localStorage.setItem('raduga-students',JSON.stringify(students));window.firebaseSyncSave?.(cloudSnapshot(),immediate)};
function esc(s=''){return String(s).replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]))}
function toast(text){const el=$('#toast');el.textContent=text;el.classList.add('show');clearTimeout(toast.t);toast.t=setTimeout(()=>el.classList.remove('show'),2400)}
function validUrl(url){if(!url)return false;try{const u=new URL(url);return ['http:','https:'].includes(u.protocol)}catch{return false}}
function normalizeUrl(value=''){let url=String(value).trim();const markdown=url.match(/^\[[^\]]*\]\((https?:\/\/[^)]+)\)$/);if(markdown)url=markdown[1];if(url&&!/^https?:\/\//i.test(url))url='https://'+url;return url}
function renderGroups(){const q=$('#search').value.trim().toLowerCase();const shown=groups.filter(g=>(level==='all'||g.level===level)&&[g.name,g.topic,g.level].join(' ').toLowerCase().includes(q));$('#count').textContent=`${shown.length} ${shown.length===1?'группа':shown.length<5?'группы':'групп'}`;$('#cards').innerHTML=shown.length?shown.map(g=>{const image=validUrl(g.cover)?`background-image:linear-gradient(#0013,#0013),url('${esc(g.cover)}')`:'';return `<article class="card" data-id="${g.id}"><div class="cover ${image?'has-image':''}" style="--c1:${g.colors?.[0]||'#168b68'};--c2:${g.colors?.[1]||'#075141'};${image}"><strong>${esc(g.series||g.name).replace(/\n/g,'<br>')}</strong><small>${esc(g.icon||'✦')}</small><em>${esc(g.num||g.level)}</em></div><button class="menu-card" data-action="menu">•••</button><div class="card-menu hidden"><button data-action="edit">Изменить</button><button class="delete" data-action="delete">Удалить</button></div><div class="card-body"><h2>${esc(g.name)}</h2><p class="meta">${esc(g.age)} <b>${esc(g.level)}</b></p><p class="topic">Тема сейчас: ${esc(g.topic||'Не указана')}</p><div class="tags"><button class="tag" data-action="resources" data-kind="pdf">PDF</button><button class="tag" data-action="resources" data-kind="book">BOOK</button><button class="tag" data-action="resources" data-kind="link">LINKS</button></div><div class="actions"><button class="open-card" data-action="open">${validUrl(g.url)?'Открыть группу ↗':'Добавить ссылку ＋'}</button><button class="mini ${favorites.includes(g.id)?'saved':''}" data-action="favorite">${favorites.includes(g.id)?'♥':'♡'}</button></div></div></article>`}).join(''):'<div class="empty">Ничего не найдено. Добавьте первую группу или измените фильтр.</div>'}
function renderExamBlocks(){const oge=[['speaking','◯','Устная часть','Задания и тренажёры'],['listening','♫','Аудирование','Аудио и практика'],['reading','▱','Чтение','Тексты и задания'],['grammar','✎','Грамматика и лексика','Правила и практика'],['writing','✉','Письмо','Шаблоны и критерии']],vpr=[['grade4','▱','ВПР 4 класс','Материалы и задания для подготовки'],['grade5','▤','ВПР 5 класс','Материалы и задания для подготовки'],['grade6','✎','ВПР 6 класс','Материалы и задания для подготовки'],['grade7','▥','ВПР 7 класс','Материалы и задания для подготовки'],['grade8','◇','ВПР 8 класс','Материалы и задания для подготовки']];const items=view==='vpr'?vpr:oge;$('#examBlocks').innerHTML=items.map(x=>`<button class="${examSection===x[0]?'active':''}" data-section="${x[0]}"><i>${x[1]}</i><span><strong>${x[2]}</strong><small>${x[3]}</small></span><b>→</b></button>`).join('')}
function renderResources(){const q=$('#search').value.trim().toLowerCase();const examView=['oge','vpr'].includes(view),collectionOk=r=>view==='library'?(r.collection||'library')==='library':view==='materials'?r.collection==='materials':true;const shown=resources.filter(r=>(resourceKind==='all'||r.kind===resourceKind)&&collectionOk(r)&&(!examView||r.course===view)&&(examSection==='all'||(r.section||'general')===examSection)&&[r.title,r.note,r.level].join(' ').toLowerCase().includes(q));const icons={book:'▱',pdf:'PDF',link:'↗',lesson:'☷',presentation:'▣',cards:'▤',game:'✦',worksheet:'▧'};$('#resources').innerHTML=shown.length?shown.map(r=>{const url=normalizeUrl(r.url),source=r.fileId?'Файл на компьютере':validUrl(url)?(url.includes('yandex.')?'Яндекс Диск':'Внешняя ссылка'):'Ссылка не добавлена';return `<article class="resource" data-id="${esc(r.id)}" data-kind="${r.kind}"><div class="resource-icon">${icons[r.kind]||'▤'}</div><div><h3>${esc(r.title)}</h3><p>${esc(r.level)} · ${esc(r.note||'Без описания')}${r.fileName?`<br>📎 ${esc(r.fileName)}`:''}</p><span class="resource-source ${!r.fileId&&!validUrl(url)?'missing':''}">${source}</span></div><div class="resource-actions"><button data-r-action="open" title="Открыть материал">↗</button><button data-r-action="edit" title="Изменить">✎</button><button class="direct-delete" data-r-action="delete" title="Удалить материал">•••</button></div></article>`}).join(''):'<div class="empty">В этом разделе пока нет материалов. Нажмите «Добавить материал».</div>'}
function renderProgress(){const total=tasks.length,done=tasks.filter(t=>t.done).length,percent=total?Math.round(done/total*100):0;$('#progressPercent').textContent=`${percent}%`;$('#progressRing').style.background=`radial-gradient(circle,#062126 57%,transparent 59%),conic-gradient(#00d787 0 ${percent}%,#123c3b ${percent}%)`;$('#progressText').textContent=total?`${done} из ${total} задач выполнено. ${percent===100?'План завершён!': 'Продолжайте в том же духе.'}`:'Добавьте задачи в план подготовки.';if(examDate){const today=new Date();today.setHours(0,0,0,0);const days=Math.ceil((new Date(examDate+'T00:00:00')-today)/86400000);$('#examCountdown').textContent=days>0?`До экзамена ${days} ${days%10===1&&days%100!==11?'день':days%10>=2&&days%10<=4&&(days%100<10||days%100>=20)?'дня':'дней'}`:days===0?'Экзамен сегодня':`Экзамен прошёл ${Math.abs(days)} дн. назад`}else $('#examCountdown').textContent='Укажите дату экзамена'}
function renderTasks(){const names={grammar:'Грамматика и лексика',listening:'Аудирование',reading:'Чтение',writing:'Письмо',speaking:'Устная часть'};const shown=tasks.filter(t=>taskStatus==='all'||(taskStatus==='done'?t.done:!t.done)).sort((a,b)=>String(a.due).localeCompare(String(b.due)));$('#planScore').textContent=`${tasks.filter(t=>t.done).length} из ${tasks.length}`;$('#taskList').innerHTML=shown.length?shown.map(t=>{const r=resources.find(x=>String(x.id)===String(t.resourceId));return `<article class="task ${t.done?'done':''}" data-task-id="${t.id}"><button class="task-check" data-task-action="toggle" aria-label="Изменить статус">${t.done?'✓':''}</button><div><h3>${esc(t.title)}</h3><p>${names[t.section]||esc(t.section)} · до ${new Date(t.due+'T00:00:00').toLocaleDateString('ru-RU',{day:'numeric',month:'long'})}</p>${r?`<a href="${esc(r.url)}" target="_blank" rel="noopener">Открыть материал ↗</a>`:''}</div><button class="task-edit" data-task-action="edit">✎</button><button class="task-delete" data-task-action="delete">×</button></article>`}).join(''):'<div class="plan-empty">Задач пока нет. Добавьте первый шаг подготовки.</div>';renderProgress()}
function openTaskForm(t){const f=$('#taskForm');f.reset();f.classList.remove('hidden');$('#taskResource').innerHTML='<option value="">Без материала</option>'+resources.filter(r=>(r.course||'general')==='oge'||(r.course||'general')==='general').map(r=>`<option value="${r.id}">${esc(r.title)}</option>`).join('');if(t)Object.keys(t).forEach(k=>{if(f.elements[k])f.elements[k].value=t[k]});else{f.elements.id.value='';f.elements.due.value=new Date(Date.now()+7*86400000).toISOString().slice(0,10)}f.elements.title.focus()}
function renderHome(){const now=new Date(),hour=now.getHours(),hello=hour<12?'Доброе утро':hour<18?'Добрый день':'Добрый вечер';$('#greeting').textContent=`${hello}, Marina!`;$('#todayDate').textContent=now.toLocaleDateString('ru-RU',{weekday:'long',day:'numeric',month:'long',year:'numeric'});const times=['10:00','12:30','15:00'];$('#lessonList').innerHTML=groups.slice(0,3).map((g,i)=>`<article><time>${times[i]}</time><div class="lesson-mark" style="--lesson-color:${g.colors?.[0]||'#00d884'}">${esc(g.num||g.level)}</div><div><h3>${esc(g.name)}</h3><p>${esc(g.topic||'Тема не указана')} · ${esc(g.level)}</p></div><button data-home-group="${g.id}">${validUrl(g.url)?'Открыть урок　↗':'Добавить ссылку　＋'}</button></article>`).join('');renderDayTasks();const recent=resources.slice(0,3),icons={book:'▱',pdf:'PDF',link:'↗',lesson:'☷',presentation:'▣',cards:'▤',game:'✦',worksheet:'▧'};$('#recentResources').innerHTML=recent.length?recent.map(r=>`<button data-home-resource="${esc(r.id)}"><i>${icons[r.kind]||'▤'}</i><span><strong>${esc(r.title)}</strong><small>${r.collection==='materials'?'Собственная разработка':'Библиотека'} · ${esc(r.level)}</small></span><b>›</b></button>`).join(''):'<div class="home-empty">Добавьте первый материал</div>';const done=tasks.filter(t=>t.done).length,percent=tasks.length?Math.round(done/tasks.length*100):0;$('#quickProgress').textContent=`Прогресс ${percent}%`;$('#homeStats').innerHTML=`<div><strong>${groups.length}</strong><span>групп</span></div><div><strong>${resources.length}</strong><span>материалов</span></div><div><strong>${dayTasks.filter(t=>!t.done).length}</strong><span>задач сегодня</span></div><div><strong>${percent}%</strong><span>план ОГЭ</span></div>`}
function renderDayTasks(){$('#dayTasks').innerHTML=dayTasks.length?dayTasks.map(t=>`<div class="day-task ${t.done?'done':''}" data-day-id="${t.id}"><button data-day-action="toggle">${t.done?'✓':''}</button><span>${esc(t.title)}</span><button data-day-action="delete">×</button></div>`).join(''):'<div class="home-empty">На сегодня всё выполнено ✦</div>'}
function startOfWeek(date){const d=new Date(date),day=(d.getDay()+6)%7;d.setHours(0,0,0,0);d.setDate(d.getDate()-day);return d}function isoDate(d){return new Date(d.getTime()-d.getTimezoneOffset()*60000).toISOString().slice(0,10)}function addDays(d,n){const x=new Date(d);x.setDate(x.getDate()+n);return x}
function renderSchedule(){const days=['Пн','Вт','Ср','Чт','Пт','Сб','Вс'],today=isoDate(new Date());$('#weekHead').innerHTML='<div></div>'+days.map((name,i)=>{const d=addDays(scheduleStart,i);return `<button class="${isoDate(d)===today?'today':''}" data-schedule-date="${isoDate(d)}"><strong>${name}</strong><span>${d.getDate()} ${d.toLocaleDateString('ru-RU',{month:'short'}).replace('.','')}</span></button>`}).join('');$('#timeColumn').innerHTML=Array.from({length:13},(_,i)=>`<span>${String(i+8).padStart(2,'0')}:00</span>`).join('');$('#weekGrid').innerHTML='<div class="grid-lines">'+Array.from({length:7},()=>'<i></i>').join('')+'</div>'+lessons.filter(l=>{const d=new Date(l.date+'T00:00:00');return d>=scheduleStart&&d<addDays(scheduleStart,7)}).map(l=>{const g=groups.find(x=>String(x.id)===String(l.groupId)),date=new Date(l.date+'T00:00:00'),day=(date.getDay()+6)%7,[h,m]=l.time.split(':').map(Number),top=((h-8)*60+m)/780*100,height=Number(l.duration)/780*100;return `<button class="lesson-event" data-lesson-id="${l.id}" style="--day:${day};--top:${top}%;--height:${height}%;--event-color:${l.color}"><strong>${esc(g?.name||'Группа')}</strong><span>${esc(l.time)} – ${endTime(l.time,l.duration)}</span>${l.note?`<small>${esc(l.note)}</small>`:''}</button>`}).join('');renderMiniCalendar();$('#scheduleGroupList').innerHTML=groups.slice(0,6).map((g,i)=>`<div><i style="background:${g.colors?.[0]||'#00d884'}"></i><span><strong>${esc(g.name)}</strong><small>${esc(g.age)} · ${esc(g.level)}</small></span><b>${lessons.filter(l=>String(l.groupId)===String(g.id)).length}</b></div>`).join('')}
function renderCalendarView(){if(calendarView==='week'){renderSchedule();return}const canvas=$('#calendarCanvas');if(calendarView==='day'){const date=selectedScheduleDate,iso=isoDate(date),items=lessons.filter(l=>l.date===iso).sort((a,b)=>a.time.localeCompare(b.time));canvas.innerHTML=`<div class="day-view-head"><button data-day-date="${iso}"><strong>${date.toLocaleDateString('ru-RU',{weekday:'long'})}</strong><span>${date.toLocaleDateString('ru-RU',{day:'numeric',month:'long',year:'numeric'})}</span></button></div><div class="day-agenda">${items.length?items.map(l=>{const g=groups.find(x=>String(x.id)===String(l.groupId));return `<button data-lesson-id="${l.id}" style="--event-color:${l.color}"><time>${l.time}<small>${endTime(l.time,l.duration)}</small></time><i></i><span><strong>${esc(g?.name||'Группа')}</strong><small>${esc(l.note||g?.topic||'Занятие')}</small></span><b>›</b></button>`}).join(''):`<div class="calendar-empty"><strong>На этот день занятий нет</strong><button data-add-on-date="${iso}">＋ Добавить занятие</button></div>`}</div>`}else{const y=selectedScheduleDate.getFullYear(),m=selectedScheduleDate.getMonth(),first=new Date(y,m,1),offset=(first.getDay()+6)%7,count=new Date(y,m+1,0).getDate();canvas.innerHTML=`<div class="month-view-head"><h3>${selectedScheduleDate.toLocaleDateString('ru-RU',{month:'long',year:'numeric'})}</h3></div><div class="month-weekdays">${['Пн','Вт','Ср','Чт','Пт','Сб','Вс'].map(x=>`<span>${x}</span>`).join('')}</div><div class="month-grid">${Array.from({length:offset},()=>'<div class="outside"></div>').join('')}${Array.from({length:count},(_,i)=>{const date=new Date(y,m,i+1),iso=isoDate(date),items=lessons.filter(l=>l.date===iso);return `<button class="month-day ${iso===isoDate(new Date())?'today':''}" data-month-date="${iso}"><b>${i+1}</b>${items.slice(0,3).map(l=>{const g=groups.find(x=>String(x.id)===String(l.groupId));return `<span style="--event-color:${l.color}">${l.time} ${esc(g?.name||'Группа')}</span>`}).join('')}${items.length>3?`<small>+ ещё ${items.length-3}</small>`:''}</button>`}).join('')}</div>`}renderMiniCalendar();$('#scheduleGroupList').innerHTML=groups.slice(0,6).map(g=>`<div><i style="background:${g.colors?.[0]||'#00d884'}"></i><span><strong>${esc(g.name)}</strong><small>${esc(g.age)} · ${esc(g.level)}</small></span><b>${lessons.filter(l=>String(l.groupId)===String(g.id)).length}</b></div>`).join('')}
function endTime(time,duration){const [h,m]=time.split(':').map(Number),total=h*60+m+Number(duration);return `${String(Math.floor(total/60)).padStart(2,'0')}:${String(total%60).padStart(2,'0')}`}
function renderMiniCalendar(){const y=miniDate.getFullYear(),m=miniDate.getMonth(),first=new Date(y,m,1),start=(first.getDay()+6)%7,count=new Date(y,m+1,0).getDate(),today=isoDate(new Date());$('#miniMonth').textContent=miniDate.toLocaleDateString('ru-RU',{month:'long',year:'numeric'});$('#miniDays').innerHTML=Array.from({length:start},()=>'<span></span>').join('')+Array.from({length:count},(_,i)=>{const d=new Date(y,m,i+1),iso=isoDate(d),has=lessons.some(l=>l.date===iso);return `<button class="${iso===today?'today':''} ${has?'has-lesson':''}" data-mini-date="${iso}">${i+1}</button>`}).join('')}
